package tri_lion.health.domain.user;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import lombok.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="user_health_profiles") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class HealthProfile { @Id @Column(name="user_id") private Long userId; @Column(name="birth_date") private LocalDate birthDate; private String gender; @Column(name="height_cm") private BigDecimal heightCm; @Column(name="weight_kg") private BigDecimal weightKg; @Column(name="target_weight_kg") private BigDecimal targetWeightKg; @Column(name="activity_level") private String activityLevel; @Column(name="available_exercise_minutes") private Integer availableExerciseMinutes; @JdbcTypeCode(SqlTypes.JSON) @Column(name="exercise_days") private String exerciseDays; @JdbcTypeCode(SqlTypes.JSON) @Column(name="dietary_preferences") private String dietaryPreferences; @JdbcTypeCode(SqlTypes.JSON) private String allergies; @JdbcTypeCode(SqlTypes.JSON) @Column(name="disliked_foods") private String dislikedFoods; @Column(name="updated_at") private Instant updatedAt; public HealthProfile(Long id){userId=id;} public void update(LocalDate b,String g,BigDecimal h,BigDecimal w,BigDecimal t,String a,Integer m,String days,String diet,String allergies,String disliked){birthDate=b;gender=g;heightCm=h;weightKg=w;targetWeightKg=t;activityLevel=a;availableExerciseMinutes=m;exerciseDays=days;dietaryPreferences=diet;this.allergies=allergies;dislikedFoods=disliked;updatedAt=Instant.now();}}
